import {section,table as plainTable,cite,topic,mountTopic} from './topic-tools.js';
import {texEq as eq,inlineMath} from './math.js';
import {decisionTree,decisionLeaves,findDecision,decisionPath,matchDecisions,workEstimate} from './choosing-model.js';
import {registerReaderState} from './reader-state.js';
export const choosingMeta={slug:'algorithms/choosing',title:'Choosing Algorithms',description:'Use constraints, output contracts and proof conditions to choose algorithms: a navigable decision tree, work/memory estimates, signed-window counterexamples and subset-sum regimes.',date:'2026-04-08',updated:'2026-10-18',topicPath:['algorithms'],tags:['constraints','complexity','decision tree','algorithm selection','NeetCode','brute force','meet-in-the-middle','subset sum','dynamic programming','greedy','hashing','BFS','DFS','sliding window','memory'],learningGoals:['Separate feasible cost from a valid algorithm.','Choose candidates through operation and structure, not keywords alone.','Count every dimension, query, state and output.'],prototype:true,visibility:'public',kind:'dense-topic',related:['algorithms/graphs','algorithms/dp','algorithms/greedy','algorithms/ordering']};
export const choosingAliases=[];
export const choosingSections=[['contract','Start with the requested answer'],['decision-lab','Follow a decision path'],['connections','Connections: objective before traversal'],['sequences','Sequences: order and contiguity'],['choices','Choices: preserve or compress the future'],['operations','Operations: choose the maintained state'],['mathematics','Mathematics: use a real invariant'],['work','Estimate the baseline work'],['work-lab','Change n without predicting wall-clock time'],['bounds','Use bounds to form hypotheses'],['pair','Replace repeated work, not the objective'],['subset-sum','Subset sum has several size variables'],['signed','A lost prefix can become valid later'],['dimensions','Count dimensions, queries and representation'],['proof','Ask what a step is allowed to discard'],['practice','Turn the candidate into a tested contract'],['sources','Sources and related mechanisms']];
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const table=(caption,heads,rows)=>plainTable(caption,heads,rows).replace('<div class="dense-table-wrap">',`<div class="dense-table-wrap" tabindex="0" role="region" aria-label="${escape(caption.startsWith('Different models of work')?'Work estimate table':caption)}">`);
const targetLink=(target,link)=>{const [slug,anchor]=target.split('#');return link(slug)+(anchor?'#'+anchor:'');};
const costFormulas={'2⁴⁰':'2^{40}','2²⁰':'2^{20}','O(n·2^(n/2))':'O(n\\,2^{n/2})','O(2^(n/2))':'O(2^{n/2})','O(K+N log(max(2,K)))':'O(K+N\\log(\\max(2,K)))','O(n log(max(2,k)))':'O(n\\log(\\max(2,k)))','O((V+E) log V)':'O((V+E)\\log V)','O(C log U)':'O(C\\log U)','O(n log n)':'O(n\\log n)','O(log n)':'O(\\log n)','O(n·2ⁿ)':'O(n\\,2^n)','Θ(n·2ⁿ)':'\\Theta(n\\,2^n)','Ω(n·n!)':'\\Omega(n\\,n!)','O(V+E)':'O(V+E)','O(n²)':'O(n^2)','O(V³)':'O(V^3)','O(V²)':'O(V^2)','O(nS)':'O(nS)','O(nm)':'O(nm)','O(RC)':'O(RC)','O(VE)':'O(VE)','O(1)':'O(1)','O(n)':'O(n)','O(h)':'O(h)','O(k)':'O(k)','O(N)':'O(N)','O(L)':'O(L)'};
const costPattern=new RegExp(Object.keys(costFormulas).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
function costText(text){let result='',last=0;for(const m of text.matchAll(costPattern)){result+=escape(text.slice(last,m.index))+inlineMath(costFormulas[m[0]]);last=m.index+m[0].length;}return result+escape(text.slice(last));}
function leafText(node,link){return `<p><strong>${escape(node.method)}</strong>. ${escape(node.condition)}</p><p><b>What can break it:</b> ${costText(node.counterexample)}</p><p><b>Cost:</b> ${costText(node.cost)} <a data-decision-target="${escape(node.target)}" href="${targetLink(node.target,link)}">Open the mechanism →</a></p>`;}
function referenceTree(node,link,depth=0){const heading=Math.min(4,depth+2);return node.children?`${depth?`<h${heading}>${escape(node.label)}</h${heading}>`:''}${node.children.map(child=>referenceTree(child,link,depth+1)).join('')}`:`<div class="decision-reference"><h${heading}>${escape(node.label)}</h${heading}>${leafText(node,link)}</div>`;}
function explorerBody(id,link){const node=findDecision(id),path=decisionPath(id);return `<nav aria-label="Current decision path" class="decision-trail">${path.map((n,i)=>i===path.length-1?`<strong tabindex="-1" data-decision-current>${escape(n.label)}</strong>`:`<button type="button" data-decision="${n.id}">${i===0?'Start':escape(n.label)}</button><span aria-hidden="true">›</span>`).join('')}</nav>${node.children?`<p>Choose the operation that matters. These branches can be combined; return to a parent to investigate another candidate.</p><div class="decision-options">${node.children.map(child=>`<button type="button" data-decision="${child.id}">${escape(child.label)} <span aria-hidden="true">→</span></button>`).join('')}</div>`:`<h3>${escape(node.label)}</h3>${leafText(node,link)}<p>This is a candidate, not a proof. Check its assumptions against the actual statement before implementing it.</p>`}`;}
const number=x=>x.toLocaleString('en-US');
const expression=s=>inlineMath(s);
choosingSections.splice(choosingSections.findIndex(([id])=>id==='work-lab'),0,['operation-costs','Cost one operation, then count repetitions']);
function estimateBody(n,q){
  const w=workEstimate(n,q),gb=new Intl.NumberFormat('en-US',{maximumSignificantDigits:6}).format(Number(w.tableBytes)/1e9);
  const rows=[['n',number(w.linear),'One pass over explicit input'],[expression('n\\log_2 n'),'≈ '+number(Math.round(w.nlogn)),'Growth model, not an exact comparison count'],[expression('\\frac{n(n-1)}{2}'),number(w.pairs),'All unordered distinct-index pairs'],[expression('n^3'),number(w.cube),'One unit for each ordered triple'],['nq',number(w.scans),'Scan n values for each of q queries'],['n+q',number(w.prefix),'Growth model for static prefix preprocessing + queries']];
  const grid=table('Different models of work; not comparable CPU instruction counts',['Expression','Count','Meaning'],rows).replace('<div class="dense-table-wrap">','<div class="dense-table-wrap" tabindex="0" role="region" aria-label="Work estimate table">');
  return `${grid}<p class="dense-caption">The table scrolls horizontally on narrow screens. Focus it to scroll with arrow keys.</p><p>An n×n table has ${number(w.tableCells)} cells. At <b>8 bytes per cell</b>, raw values alone use ${number(w.tableBytes)} bytes (≈ ${gb} decimal GB). Headers, references and other objects are excluded.</p><p>No result is marked “passes.” Hardware, operation cost, language, input/output and memory limits remain external to this model. For q=0, building a prefix table may be unnecessary.</p>`;
}
export function choosingReader(link){return topic(choosingMeta,choosingSections,'Constraints reject costs. Structure suggests a method. An invariant justifies it.',`
<p>A length bound of 100,000 is useful evidence against a pairwise scan. It does not choose between hashing, sorting, a heap or a sliding window. Those methods maintain different information and solve different questions.</p><p>Use the decision tree to produce one or two candidates. Then test the conditions and total cost. Several branches can apply at once: a shortest-path algorithm can use a heap; a board-word search can combine backtracking with a trie.</p>
${section('contract','Start with the requested answer',`<p>Write what an answer contains: one value, original indices, a count, an ordered sequence, a shortest route or every valid arrangement. Specify duplicates, ties, empty input and permitted mutation. These are part of the problem, not final implementation details.</p><p>Distinguish contiguous subarrays from subsequences. Distinguish source-to-vertex distances from total spanning-tree weight. Distinguish “can reach” from “use every edge.” The same input representation can require different algorithms because the objective changes.</p><figure class="dense-boundary"><ol><li>Specify the answer contract.</li><li>Write a correct baseline.</li><li>Estimate its total cost.</li><li>Use input structure to propose a better method.</li><li>Prove why the method is correct.</li><li>Test the conditions and edge cases.</li></ol><figcaption>A small input allows expensive work; it does not require an expensive solution. Return to an earlier step when a proof or counterexample changes the model.</figcaption></figure><p>A roadmap organizes study topics. This reader instead organizes the questions needed when an unfamiliar statement arrives. The static sections below contain every decision path, including its failure condition.</p>`)}
<section id="decision-lab" class="dense-section dense-lab decision-explorer"><header><h2>Follow a decision path</h2><p>Choose a family, then an operation. Search matches labels, conditions, counterexamples and costs across all ${decisionLeaves.length} leaves.</p></header><label>Find a decision<input type="search" data-decision-search placeholder="Try signed sum, negative weights, prefix…"></label><div data-decision-results aria-live="polite"></div><div data-decision-body>${explorerBody('root',link)}</div></section>
${section('connections','Connections: objective before traversal',`<p>A state and its legal transitions form a graph even when the statement describes cells, moves or dependencies. A tree supplies additional structure: one parent path and independent child subtrees.</p><p>For equal-cost moves, BFS layers give shortest edge counts. Weighted distances require relaxation. Negative cycles affect only reachable destinations whose routes can pass through them; they do not invalidate every pair automatically. Grid right/down counting can use acyclic DP, while a no-revisit word path must keep branch-specific visited state.</p>${referenceTree(decisionTree.children[0],link)}`)}
${section('sequences','Sequences: order and contiguity',`<p>Ask which relationship the answer preserves. A complement lookup preserves a previously seen value; a window preserves a contiguous range; a monotonic stack preserves unresolved candidates. None follows merely from the word “array.”</p><p>Sorted order makes some eliminations safe. For a pair sum, increasing the left value cannot decrease the sum. For a target boundary, comparison can rule out a half. Those arguments fail if the claimed ordering does not hold.</p><p>An alphabet restricted to 26 lowercase English letters permits a fixed frequency array when the caller checks that domain. For sorted triplets, fix one index and scan the remaining pair with two pointers. This adds an outer factor: the usual scan costs O(n²), not the pair scan's O(n). Sorting may add preprocessing and must preserve original indices when requested.</p>${referenceTree(decisionTree.children[1],link)}`)}
${section('choices','Choices: preserve or compress the future',`<p>Enumeration preserves distinct paths. DP merges histories only when their future options and costs agree. Greedy commits a choice only when an exchange or dominance proof makes alternatives unnecessary.</p><p>“Minimum,” “maximum” and “number of ways” name outputs, not algorithm families. Minimum hops may be BFS. Maximum compatible interval count may be greedy. A binary search may call a greedy feasibility test. A DP may run on a tree.</p>${referenceTree(decisionTree.children[2],link)}`)}
${section('operations','Operations: choose the maintained state',`<p>Choose a data structure by the repeated operation that would otherwise be expensive. A heap maintains the current extreme, not full order. A trie shares prefix work, not arbitrary substring lookup. A stack preserves pending last-in-first-out work.</p><p>Intervals make this distinction concrete. Sort starts to merge coverage. Sort finishes to maximize an unweighted compatible count. Track active endpoints to count simultaneous demand. Weighted rewards change the objective and usually require a different recurrence.</p>${referenceTree(decisionTree.children[3],link)}`)}
${section('mathematics','Mathematics: use a real invariant',`<p>Arithmetic shortcuts need an input contract too. Pair cancellation uses exact multiplicities. A coordinate transform needs its origin and orientation. A repeated process needs a sufficient state before cycle detection is valid.</p>${referenceTree(decisionTree.children[4],link)}`)}
${section('work','Estimate the baseline work',`<p>Describe a correct straightforward solution before improving it. Count the operation repeated most often, then substitute the maximum input sizes. Do not multiply loop bounds blindly: a pointer or stack entry can be processed only a constant number of times despite nested syntax.</p>${table('At n=100,000, growth separates candidate costs',['Growth expression','Count'],[['n','100,000'],[expression('n\\log_2 n'),'Approximately 1.66 million'],[expression('n^2'),'10 billion'],[expression('n^3'),'1 quadrillion']])}<p>Big-O gives an asymptotic upper bound. It is not a measured duration and does not identify the constant factor. State whether a bound is worst-case, expected or amortized. Expected hashing depends on key distribution, load management and hash/equality cost; it is not an unconditional worst-case constant guarantee.</p><p>${cite('https://algs4.cs.princeton.edu/14analysis/','Cost models and input-dependent guarantees')} · ${cite('https://algs4.cs.princeton.edu/34hash/','Hashing assumptions and key work')}</p>`)}
${section('operation-costs','Cost one operation, then count repetitions',`${table('A data structure accelerates a specific operation',['Structure / operation','Cost','Condition'],[['Binary heap: inspect the root',expression('O(1)'),'Existing nonempty heap; min or max depends on direction'],['Binary heap: insert or remove the root',expression('O(\\log n)'),'Worst-case repair path; bounded-cost comparison'],['Binary heap: build from an array',expression('O(n)'),'Bottom-up heapify, not repeated insertion'],['Hash table: membership / insert / remove','Expected amortized '+expression('O(1)'),'Suitable hashing/load policy and bounded-cost keys; not universal worst case']])}<p>Here n is the number of stored entries. Multiplying a per-operation cost by the number of operations gives a whole-task estimate. Hashing a long string adds key work. A balanced binary heap is partially ordered; its array is not a sorted sequence. <a href="${link('algorithms/ordering#heap')}">Heap invariant →</a></p>`)}
<section id="work-lab" class="dense-section dense-lab"><header><h2>Change n without predicting wall-clock time</h2><p>Integer n ranges from 1 to 1,000,000; q ranges from 0 to 1,000,000. Counts use exact integer arithmetic where the expression is integer-valued.</p></header><div class="estimate-controls"><label>Input length n<input type="number" data-estimate-n min="1" max="1000000" step="1" value="100000"></label><label>Query count q<input type="number" data-estimate-q min="0" max="1000000" step="1" value="100000"></label></div><div data-estimate-body aria-live="polite">${estimateBody(100000,100000)}</div></section>
${section('bounds','Use bounds to form hypotheses',`${table('Study heuristics, not judge-specific pass thresholds',['Maximum size','Candidate work','What to investigate'],[['About 8–10','n!','Permutation enumeration; include output copying'],['About 20','2ⁿ or n·2ⁿ','Subsets, small-universe bitmask state'],['About 40',expression('2^{n/2}')+' with combination factors','Meet-in-the-middle if the choices split'],['About 100–300','n³ may fit','Interval DP, all-pairs distances'],['About 1,000–3,000','n² may fit','Pairs, quadratic DP'],['About 100,000','Usually n log n or n','Sorting, heaps, hashing, pointers'],['About 1,000,000','Prefer near-linear work','Scans, counting, prefix summaries; sorting may still fit']])}<p>These approximate ranges generate candidates. They are not universal runtime budgets. ${expression("20\\cdot2^{20}")} is 20,971,520 state-transition-scale operations, and objects for all states can dominate memory. A simple linear method remains preferable when it is also correct on ten values.</p><p>A scalar as large as ${expression("10^{18}")} may support logarithmic answer search or arithmetic. An explicit n-element input still needs Ω(n) inspection when every element can affect the answer. Numeric magnitude and amount of input are different variables. ${cite('https://usaco.guide/bronze/time-comp','Constraint heuristics and constant-factor caveats')}</p>`)}
${section('pair','Replace repeated work, not the objective',`<p>For two distinct indices whose values sum to a target, brute force checks each unordered pair once. At n=100,000, this is 4,999,950,000 checks. The size bound rejects that cost, but does not supply a faster algorithm.</p>${eq("\\binom{n}{2}=\\frac{n(n-1)}{2}=4{,}999{,}950{,}000", "n=100,000 indexed values. The general pair formula holds for nonnegative integer n; pairs use distinct indices and order does not matter.")}<p>The relationship supplies the improvement: for value x, only target−x can be its partner. Store previously seen values and look up that complement before inserting x. Lookup-before-insertion prevents reusing the current index. Expected time becomes O(n), with O(n) extra state under bounded-cost hashing.</p><pre tabindex="0" role="region" aria-label="Pair sum Python"><code>def two_sum(nums, target):
    seen = {}
    for i, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], i]
        seen[value] = i
    return None</code></pre><p>This callable function accepts integer values and an integer target. It does not mutate the input. It returns one valid index pair, or None when none exists. Repeated values replace their earlier stored index; any returned pair still contains distinct indices. It does not enumerate all pairs.</p><p>Sorting plus two pointers is another valid candidate. Preserve original indices if the output needs them; sorting adds work and may mutate caller data. Already sorted input supports a direct O(n) pair scan. The <a href="${link('algorithms/arrays')}#complement-lab">complement trace →</a> and <a href="${link('algorithms/windows')}#pair-lab">sorted-pair trace →</a> expose the distinct invariants.</p>`)}
${section('subset-sum','Subset sum has several size variables',`<p>Suppose each value can be selected once, and ask whether some subset totals S. Three regimes illustrate why length alone is insufficient.</p>${table('One objective, different representations',['Regime','Method','Work/storage condition'],[['About n=20','Enumerate subsets',inlineMath(String.raw`2^{20}=1{,}048{,}576`)+' leaves; carry the sum instead of rebuilding it'],['About n=40','Split, enumerate half sums, find complements',inlineMath(String.raw`2^{40}=1{,}099{,}511{,}627{,}776`)+' full subsets; two halves have '+inlineMath(String.raw`2^{20}`)+' sums each'],['Many values, small nonnegative integer S','Reachable-sum DP','O(nS) time and O(S) rolling storage, with descending updates for one-use items']])}<p>Meet-in-the-middle combines a left sum a with right sum S−a. Generating half sums recursively takes work proportional to their number. Sorting one list and searching for each complement introduces logarithmic factors, giving the typical ${expression("O(n\\,2^{n/2})")} time bound and ${expression("O(2^{n/2})")} storage.</p><p>The O(nS) method is pseudo-polynomial: its cost depends on the numeric value S, not only the ${expression("O(1+\\log(S+1))")} bits needed to encode nonnegative S. Nonnegative values permit discarding sums above a nonnegative target; signed values require a different reachable range or representation. <a href="${link('algorithms/dp')}#reuse">The item-reuse trace →</a> shows why update direction changes the problem.</p>`)}
${section('signed','A lost prefix can become valid later',`<p>For nonnegative values, adding an element cannot decrease a window sum, and removing its left element cannot increase it. This supports some forward-only boundary rules. It does not prove every sum problem is a window problem.</p><p>For target 3, [5,−2] is valid even though the first prefix is 5. Removing 5 immediately because it exceeds the target loses the later answer. Prefix sums avoid that assumption: a subarray totals target exactly when an earlier prefix equals current prefix minus target.</p><pre tabindex="0" role="region" aria-label="Exact sum Python"><code>
def count_exact_sum(values, target):
    frequency = {0: 1}
    prefix = answer = 0
    for value in values:
        prefix += value
        answer += frequency.get(prefix - target, 0)
        frequency[prefix] = frequency.get(prefix, 0) + 1
    return answer</code></pre><p>The function accepts integers, counts nonempty subarrays, and leaves the input unchanged. Empty input returns zero. Query before inserting the current prefix so it cannot match itself as an empty subarray. Counts, rather than presence alone, preserve repeated prefixes. For [0,0] and target 0, three nonempty subarrays match; the empty prefix initializes the map but is not an extra answer. For no-repeat substrings, counts supply another monotone validity rule; <a href="${link('algorithms/windows')}#unique-lab">watch its boundary repair →</a>.</p>`)}
${section('dimensions','Count dimensions, queries and representation',`${table('The hidden quantity can change feasibility',['Quantity','Account for it'],[['Grid','R·C cells, not just rows'],['Graph','V vertices and E edges; sparse versus dense representation'],['Strings','Hashing/comparison can inspect L characters'],['DP','Reachable states × transitions, plus reconstruction/output'],['Queries','Preprocessing + q query costs + update costs'],['Test cases','Use a stated total-length bound when available'],['Memory','Cells × bytes plus container/object/reference overhead']])}<p>For n=q=100,000 static range-sum queries, scanning each range can cost O(nq). Prefix construction and subtraction queries reduce the growth model to O(n+q). Point updates invalidate a static prefix snapshot; Fenwick or segment trees support relevant aggregates with logarithmic operations.</p><p>At ${inlineMath(String.raw`n=100{,}000`)}, an ${inlineMath(String.raw`n^2`)} table has ten billion cells: about 10 decimal GB even at one byte per cell. Ordinary Python containers can require much more. Rolling rows may reduce a DP table from O(nm) to O(m), but only when dependencies permit overwriting. Reconstructing an actual solution may need extra history.</p><p>Known data does not by itself guarantee a linear heap build: bottom-up heapify does. Inserting all known values separately still costs O(n log n) in the worst case. <a href="${link('algorithms/ordering')}#heapify">Heap construction →</a> owns the proof.</p>`)}
${section('proof','Ask what a step is allowed to discard',`${table('A feasible cost is not a correctness argument',['Candidate','Necessary argument'],[['Binary search','A comparison/predicate safely removes a half and the interval shrinks'],['Window','Discarded starts cannot become better candidates later'],['DP','Equal states have equal future options/costs; recurrence and base are correct'],['Greedy','The local commitment can replace an optimum choice without worsening it'],['Backtracking','Every valid answer has a branch; every prune excludes only impossible completions'],['Heap frontier','The root is best among the candidates that correctly represent remaining work']])}<p>Coins [1,4,5] and target 8 break largest-first coin count: 5+1+1+1 needs four coins, while 4+4 needs two. Large search spaces may motivate heuristics, but do not convert them into exact solvers. ${cite('https://usaco.guide/silver/greedy-sorting','Greedy counterexamples and proof conditions')}</p><p>A shortest grid route uses global discovery state; a board-word path uses branch-local occupied cells and can prune through a trie. An acyclic prerequisite order uses directed cycle/dependency state. A warmer later value resolves a pending smaller value in a monotonic stack. A larger feasible speed supports answer search. These are invariant examples, not separate exercise pages.</p>`)}
${section('practice','Turn the candidate into a tested contract',`<ol><li>Name the answer and size variables, including target, queries, value range and total test-case size.</li><li>Describe a correct baseline and count its repeated work.</li><li>Reject time or memory costs that conflict with the actual limits.</li><li>Identify a structural property and one or two candidate methods.</li><li>State the invariant, recurrence or exchange argument before coding.</li><li>Account for setup, key work, output, mutation and reconstruction.</li><li>Compare tiny cases with brute force; test the assumption most likely to fail.</li></ol><p>Keep a brief record after solving: clue, maintained state, proof condition and why the tempting alternative fails. This is more reusable than memorizing an exercise title or associating one keyword with one algorithm.</p><p>Test empty/singleton input, equal keys, signed values, ties, repeated queries, stale state and repeated calls. A method passing samples is evidence, not a proof. If no candidate is valid, revisit the state and objective instead of selecting the cheapest-looking leaf.</p>`)}
${section('sources','Sources and related mechanisms',`<p>${cite('https://neetcode.io/roadmap','NeetCode roadmap')} · ${cite('https://algo.monster/flowchart','External algorithm-selection aid')} · ${cite('https://algs4.cs.princeton.edu/14analysis/','Algorithm analysis')} · ${cite('https://usaco.guide/bronze/time-comp','Constraint estimates')}</p><p>The decision aid is an original synthesis of the local notes, not a reproduction of the external chart. It supplies conditions and counterexamples, not a universal classifier.</p><p><a href="${link('algorithms/ordering#quicksort-lab')}">Sorting execution →</a> · <a href="${link('algorithms/trees#dfs-walk')}">Traversal frontiers →</a> · <a href="${link('algorithms/arrays#complement-lab')}">Complement lookup →</a></p>`)}
`);}
choosingMeta.searchText=choosingReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountChoosing(scope=document){mountTopic(scope,choosingMeta.slug,article=>{
  // Reuse the actual navigation URL contract from the rendered static reference.
  const links=new Map();for(const a of article.querySelectorAll('.decision-reference [data-decision-target]'))links.set(a.dataset.decisionTarget,a.href);
  const link=slug=>{const match=[...links].find(([target])=>target.split('#')[0]===slug);if(!match)throw new Error('Missing decision destination '+slug);const url=new URL(match[1]);url.hash='';return url.href;};
  const search=article.querySelector('[data-decision-search]'),results=article.querySelector('[data-decision-results]'),body=article.querySelector('[data-decision-body]');
  let current='root';
  const openDecision=(id,focus=false)=>{current=id;body.innerHTML=explorerBody(id,link);if(focus)body.querySelector('[data-decision-current]').focus({preventScroll:true});};
  article.querySelector('#decision-lab').addEventListener('click',e=>{const button=e.target.closest('[data-decision]');if(!button||!findDecision(button.dataset.decision))return;search.value='';results.innerHTML='';openDecision(button.dataset.decision,true);});
  registerReaderState(article,'algorithm-decision-path',{read:()=>({id:current}),validate:s=>typeof s?.id==='string'&&Boolean(findDecision(s.id)),write:s=>openDecision(s.id)});
  search.addEventListener('input',()=>{const matches=matchDecisions(search.value);results.innerHTML=search.value.trim()?`<p>${matches.length} matching decision${matches.length===1?'':'s'}. Select one to open its path.</p><div class="decision-options">${matches.map(leaf=>`<button type="button" data-decision="${leaf.id}">${escape(leaf.label)} — ${escape(leaf.method)}</button>`).join('')}</div>`:'';});
  const n=article.querySelector('[data-estimate-n]'),q=article.querySelector('[data-estimate-q]'),output=article.querySelector('[data-estimate-body]');
  const draw=()=>{try{if(!n.value.trim()||!q.value.trim())throw new RangeError();output.innerHTML=estimateBody(Number(n.value),Number(q.value));}catch{output.innerHTML='<p>Enter integer n in 1..1,000,000 and q in 0..1,000,000. The previous estimate is not valid for this input.</p>';}};
  n.addEventListener('input',draw);q.addEventListener('input',draw);
});}
